package cli

import (
	"flag"
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"github.com/tdeshazo/repoctx/pkg/agentctx"
	"github.com/tdeshazo/repoctx/pkg/compiler"
	"github.com/tdeshazo/repoctx/pkg/ir"
)

type repeated []string

func (v *repeated) String() string     { return strings.Join(*v, ",") }
func (v *repeated) Set(s string) error { *v = append(*v, s); return nil }

func contextCmd(args []string) {
	fs := flag.NewFlagSet("context", flag.ExitOnError)
	root := fs.String("root", "", "required path to the matching source repository")
	query := fs.String("query", "", "task text, symbol name, or path (lexical retrieval)")
	var symbols, units, allows, denies repeated
	fs.Var(&symbols, "symbol", "exact semantic ID; repeat for multiple required seeds")
	fs.Var(&units, "unit", "exact retrieval unit ID from this snapshot; repeat for required seeds")
	maxUnits := fs.Int("max-units", 8, "maximum included retrieval units, 1..64")
	fs.Var(&allows, "allow", "repeat compilation allow policy exactly; omitted scope inherits index policy")
	fs.Var(&denies, "deny", "repeat compilation deny policy exactly; repeat; deny wins")
	snapshot := fs.String("expect-snapshot", "", "required index snapshot digest when expanding prior context")
	consistency := fs.String("consistency", "verified-local", "verified-local or immutable; immutable asserts caller-isolated pinned inputs")
	depth := fs.Int("depth", 1, "graph depth 0..4; never expand unit/unresolved hubs")
	direction := fs.String("direction", "both", "in, out, or both")
	rels := fs.String("relations", "calls,defines", "comma-separated traversal relation names")
	maxBytes := fs.Int("max-bytes", 32768, "hard limit on the complete uncompressed serialized payload")
	maxSymbols := fs.Int("max-symbols", 12, "maximum included symbol records, 1..64")
	maxCandidates := fs.Int("max-candidates", 128, "maximum graph candidates, 1..4096")
	maxRelations := fs.Int("max-relations", 48, "maximum relationship records, 1..256")
	maxSource := fs.Int64("max-source-bytes", 2<<20, "per-file verification read bound")
	maxRead := fs.Int64("max-read-bytes", 256<<20, "total verification read bound")
	format := fs.String("format", "json", "json for agents, markdown for readable review")
	out := fs.String("o", "-", "output file or stdout; no compression or extra JSON re-encoding")
	_ = fs.Parse(args)
	if fs.NArg() != 1 {
		fatal(fmt.Errorf("usage: repoctx context -root DIR -query TEXT [options] REPO_IR"))
	}
	var kinds []ir.EdgeKind
	for _, r := range strings.Split(*rels, ",") {
		switch strings.TrimSpace(r) {
		case "calls":
			kinds = append(kinds, ir.EdgeCalls)
		case "defines":
			kinds = append(kinds, ir.EdgeDefines)
		case "imports":
			kinds = append(kinds, ir.EdgeImports)
		default:
			fatal(fmt.Errorf("unsupported traversal relation %q", r))
		}
	}
	repo, e := compiler.Read(fs.Arg(0))
	if e != nil {
		fatal(e)
	}
	result, e := agentctx.Build(repo, agentctx.Options{Root: *root, Query: *query, Symbols: symbols, Units: units, MaxUnits: *maxUnits, ExpectedSnapshot: *snapshot, Consistency: *consistency, Depth: *depth, Direction: *direction, Relations: kinds, MaxSymbols: *maxSymbols, MaxCandidates: *maxCandidates, MaxRelations: *maxRelations, MaxBytes: *maxBytes, Format: *format, AllowPaths: allows, DenyPaths: denies, MaxSourceBytes: *maxSource, MaxReadBytes: *maxRead})
	if e != nil {
		fatal(e)
	}
	if e := writePayload(*out, result.Payload); e != nil {
		fatal(e)
	}
	fmt.Fprintf(os.Stderr, "context: %d symbols, %d units, %d evidence blocks, %d relationships; %d bytes; approximately %d tokens (byte/4 heuristic, NOT a token bound)\n", len(result.Bundle.Symbols), len(result.Bundle.Units), len(result.Bundle.Evidence), len(result.Bundle.Relationships), result.Usage.Bytes, result.Usage.Tokens)
}

func validateCmd(args []string) {
	if len(args) != 1 {
		fatal(fmt.Errorf("usage: repoctx validate REPO_IR"))
	}
	repo, e := compiler.Read(args[0])
	if e != nil {
		fatal(e)
	}
	snapshot, e := repo.SnapshotID()
	if e != nil {
		fatal(e)
	}
	fmt.Printf("valid %s\nsnapshot: %s\n", repo.Version, snapshot)
}

// Atomically replace files after the complete bundle passes budget checks. A
// failure before rename never replaces a previously valid output. Explicit
// output paths are controlled by the caller, not inferred from repository text.
func writePayload(path string, b []byte) error {
	if path == "" || path == "-" {
		_, e := os.Stdout.Write(b)
		return e
	}
	f, e := os.CreateTemp(filepath.Dir(path), ".repoctx-context-*")
	if e != nil {
		return e
	}
	temp := f.Name()
	defer os.Remove(temp)
	if _, e = f.Write(b); e != nil {
		f.Close()
		return e
	}
	if e = f.Sync(); e != nil {
		f.Close()
		return e
	}
	if e = f.Close(); e != nil {
		return e
	}
	return os.Rename(temp, path)
}
package agentctx

import (
	"context"
	"fmt"
	"sort"
	"strings"
	"unicode"

	"github.com/tdeshazo/repoctx/pkg/ir"
)

type candidate struct {
	node   int
	reason Reason
	seed   bool
	unit   *retrievalUnit
}

func terms(s string) []string {
	var out []string
	var word []rune
	var prev rune
	for _, r := range s {
		if !unicode.IsLetter(r) && !unicode.IsDigit(r) {
			if len(word) > 0 {
				out = append(out, strings.ToLower(string(word)))
				word = nil
			}
		} else {
			if unicode.IsUpper(r) && unicode.IsLower(prev) && len(word) > 0 {
				out = append(out, strings.ToLower(string(word)))
				word = nil
			}
			word = append(word, r)
		}
		prev = r
	}
	if len(word) > 0 {
		out = append(out, strings.ToLower(string(word)))
	}
	stop := map[string]bool{"a": true, "an": true, "the": true, "to": true, "in": true, "of": true, "for": true, "and": true, "fix": true, "change": true, "how": true, "does": true, "is": true}
	seen := map[string]bool{}
	var clean []string
	for _, x := range out {
		if !stop[x] && !seen[x] {
			seen[x] = true
			clean = append(clean, x)
		}
	}
	return clean
}
func chooseSymbols(ctx context.Context, r *ir.Repository, o Options, sources map[int]*source) ([]candidate, []string, bool, error) {
	var seeds []candidate
	byID := map[string]int{}
	for i, s := range r.Symbols {
		if i&255 == 0 {
			if err := ctx.Err(); err != nil {
				return nil, nil, false, err
			}
		}
		if sources[s.File] != nil {
			byID[r.String(s.ID)] = i
		}
	}
	if len(o.Symbols) > 0 {
		seen := map[int]bool{}
		for _, id := range o.Symbols {
			i, ok := byID[id]
			if !ok {
				return nil, nil, false, fmt.Errorf("requested symbol not found in permitted index: %q", id)
			}
			if !seen[i] {
				seen[i] = true
				seeds = append(seeds, candidate{node: i, reason: Reason{Strategy: "explicit_symbol", Score: 100000}, seed: true})
			}
		}
	} else if len(o.Units) == 0 {
		words := terms(o.Query)
		var ranked []candidate
		for i, s := range r.Symbols {
			if i&255 == 0 {
				if err := ctx.Err(); err != nil {
					return nil, nil, false, err
				}
			}
			if sources[s.File] == nil {
				continue
			}
			id := r.String(s.ID)
			name := strings.ToLower(r.String(s.Name))
			qualified := strings.ToLower(id)
			p := strings.ToLower(r.String(r.Files[s.File].Path))
			exactScore, nameScore, idScore, pathScore := 0, 0, 0, 0
			q := strings.ToLower(strings.TrimSpace(o.Query))
			if q == name || q == qualified {
				exactScore = 10000
			}
			for _, t := range words {
				if t == name {
					nameScore += 100
				} else if strings.Contains(name, t) {
					nameScore += 50
				}
				if strings.Contains(qualified, t) {
					idScore += 20
				}
				if strings.Contains(p, t) {
					pathScore += 5
				}
			}
			bodyScore := 0
			if r.Files[s.File].Lang != ir.LangMarkdown {
				a, z, err := sources[s.File].offsets(r.Files[s.File].Nodes[s.Node].Span)
				if err != nil {
					return nil, nil, false, err
				}
				body := strings.ToLower(string(sources[s.File].data[a:z]))
				for _, word := range words {
					if strings.Contains(body, word) {
						bodyScore += 30
					}
				}
			}
			score := exactScore + nameScore + idScore + pathScore + bodyScore
			if score > 0 {
				fields := []string{}
				if nameScore > 0 || q == name {
					fields = append(fields, "name")
				}
				if idScore > 0 || q == qualified {
					fields = append(fields, "semantic_id")
				}
				if pathScore > 0 {
					fields = append(fields, "path")
				}
				if bodyScore > 0 {
					fields = append(fields, "body")
				}
				ranked = append(ranked, candidate{node: i, reason: Reason{Strategy: "lexical_seed", Score: score,
					MatchedFields: fields, Components: map[string]int{"exact": exactScore, "name": nameScore,
						"semantic_id": idScore, "path": pathScore, "body": bodyScore}}, seed: true})
			}
		}
		sort.Slice(ranked, func(i, j int) bool {
			if ranked[i].reason.Score != ranked[j].reason.Score {
				return ranked[i].reason.Score > ranked[j].reason.Score
			}
			return r.String(r.Symbols[ranked[i].node].ID) < r.String(r.Symbols[ranked[j].node].ID)
		})
		if len(ranked) > 0 {
			threshold := ranked[0].reason.Score / 2
			for _, c := range ranked {
				if len(seeds) >= 3 || len(seeds) >= o.MaxSymbols || len(seeds) >= o.MaxCandidates || c.reason.Score < threshold {
					break
				}
				seeds = append(seeds, c)
			}
		}
	}
	if len(seeds) == 0 {
		return nil, nil, false, nil
	}
	if len(seeds) > o.MaxSymbols || len(seeds) > o.MaxCandidates {
		return nil, nil, false, fmt.Errorf("seed count exceeds symbol/candidate limit")
	}
	wanted := map[ir.EdgeKind]bool{}
	for _, k := range o.Relations {
		wanted[k] = true
	}
	selected := map[int]candidate{}
	var queue []int
	var ids []string
	for _, c := range seeds {
		selected[c.node] = c
		queue = append(queue, c.node)
		ids = append(ids, r.String(r.Symbols[c.node].ID))
	}
	limited := false
	scanned := 0
	if r.Graph != nil {
		for q := 0; q < len(queue); q++ {
			cur := selected[queue[q]]
			if cur.reason.Depth >= o.Depth {
				continue
			}
			type direction struct {
				name string
				csr  ir.CSR
			}
			dirs := []direction{}
			if o.Direction != "in" {
				dirs = append(dirs, direction{"out", r.Graph.Out})
			}
			if o.Direction != "out" {
				dirs = append(dirs, direction{"in", r.Graph.In})
			}
			for _, d := range dirs {
				for j := d.csr.Offsets[cur.node]; j < d.csr.Offsets[cur.node+1]; j++ {
					scanned++
					if scanned&255 == 0 {
						if err := ctx.Err(); err != nil {
							return nil, nil, false, err
						}
					}
					if scanned > 100000 {
						limited = true
						break
					}
					n := int(d.csr.Targets[j])
					k := d.csr.Kinds[j]
					// Do not traverse unit hubs or globally merged unresolved names. Such
					// expansion creates spurious relationships between unrelated packages.
					if n >= len(r.Symbols) || !wanted[k] || sources[r.Symbols[n].File] == nil {
						continue
					}
					if _, ok := selected[n]; ok {
						continue
					}
					if len(selected) >= o.MaxCandidates {
						limited = true
						continue
					}
					next := candidate{node: n, reason: Reason{Strategy: "graph_neighbor", Depth: cur.reason.Depth + 1, Score: cur.reason.Score / 2, Via: r.String(r.Symbols[cur.node].ID), Relation: edgeName(k), Direction: d.name}}
					selected[n] = next
					queue = append(queue, n)
				}
				if scanned > 100000 {
					break
				}
			}
			if scanned > 100000 {
				break
			}
		}
	}
	var rest []candidate
	for _, c := range selected {
		if !c.seed {
			rest = append(rest, c)
		}
	}
	sort.Slice(rest, func(i, j int) bool {
		a, b := rest[i], rest[j]
		if a.reason.Depth != b.reason.Depth {
			return a.reason.Depth < b.reason.Depth
		}
		if a.reason.Score != b.reason.Score {
			return a.reason.Score > b.reason.Score
		}
		return r.String(r.Symbols[a.node].ID) < r.String(r.Symbols[b.node].ID)
	})
	return append(seeds, rest...), ids, limited, nil
}
func edgeName(k ir.EdgeKind) string {
	return map[ir.EdgeKind]string{ir.EdgeDefines: "defines", ir.EdgeCalls: "calls", ir.EdgeImports: "imports", ir.EdgeReferences: "references"}[k]
}
func kindName(k ir.SymbolKind) string {
	return map[ir.SymbolKind]string{ir.SymModule: "module", ir.SymType: "type", ir.SymFunction: "function", ir.SymMethod: "method", ir.SymVariable: "variable", ir.SymConstant: "constant"}[k]
}
func languageName(k ir.Language) string {
	switch k {
	case ir.LangGo:
		return "go"
	case ir.LangPython:
		return "python"
	case ir.LangHTML:
		return "html"
	case ir.LangCSS:
		return "css"
	case ir.LangJavaScript:
		return "javascript"
	case ir.LangTypeScript:
		return "typescript"
	case ir.LangTSX:
		return "tsx"
	case ir.LangMarkdown:
		return "markdown"
	default:
		return "unknown"
	}
}
package agentctx

import (
	"context"
	"encoding/hex"
	"fmt"
	"runtime"
	"slices"
	"strings"

	"github.com/tdeshazo/repoctx/pkg/ir"
)

// Build verifies indexed sources and returns a self-contained, byte-bounded
// context payload. It runs no repository commands. Use an immutable worktree:
// source reads do not create a transactional filesystem snapshot.
func Build(r *ir.Repository, o Options) (*Result, error) {
	return build(context.Background(), r, o, nil)
}

// BuildFromGeneration builds context from a previously verified, immutable
// in-memory source generation without rereading the repository filesystem.
// ExpectedSnapshot remains mandatory so the application explicitly binds its
// authenticated request to the generation it selected.
func BuildFromGeneration(g *VerifiedSourceGeneration, o Options) (*Result, error) {
	return BuildFromGenerationContext(context.Background(), g, o)
}

// BuildFromGenerationContext is BuildFromGeneration with cooperative request
// cancellation. No work is detached from ctx.
func BuildFromGenerationContext(ctx context.Context, g *VerifiedSourceGeneration, o Options) (*Result, error) {
	if ctx == nil {
		return nil, fmt.Errorf("context is required")
	}
	if g == nil {
		return nil, fmt.Errorf("verified source generation is required")
	}
	if o.Consistency != "" && o.Consistency != "immutable" {
		return nil, fmt.Errorf("verified source generation requires immutable consistency")
	}
	o.Consistency = "immutable"
	o.sourceMode = "verified-source-generation/v1"
	return build(ctx, g.repository, o, g.sources)
}

func build(ctx context.Context, r *ir.Repository, o Options, generationSources map[int]*source) (*Result, error) {
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	if e := normalize(&o, generationSources == nil); e != nil {
		return nil, e
	}
	if r == nil {
		return nil, fmt.Errorf("repository index is required")
	}
	if e := r.Validate(); e != nil {
		return nil, fmt.Errorf("invalid index: %w", e)
	}
	if r.Version != "repoctx.ir/v1alpha5" {
		return nil, fmt.Errorf("context serving requires v1alpha5 compilation-input manifests; recompile this index")
	}
	profile := r.Inputs.Profile
	if len(o.AllowPaths) != 0 || len(o.DenyPaths) != 0 {
		if !slices.Equal(ir.CanonicalPrefixes(o.AllowPaths), profile.Allow) || !slices.Equal(ir.CanonicalPrefixes(o.DenyPaths), profile.Deny) {
			return nil, fmt.Errorf("incompatible authorization scope: recompile with the requested allow/deny policy")
		}
	}
	o.AllowPaths, o.DenyPaths = profile.Allow, profile.Deny
	snap, e := r.SnapshotID()
	if e != nil {
		return nil, e
	}
	if o.ExpectedSnapshot != "" && snap != o.ExpectedSnapshot {
		return nil, fmt.Errorf("snapshot mismatch: re-resolve semantic IDs against the requested index")
	}
	sources := generationSources
	if sources == nil {
		sources, e = loadSources(r, o)
		if e != nil {
			return nil, e
		}
	}
	candidates, seeds, limited, e := choose(ctx, r, o, sources)
	if e != nil {
		return nil, e
	}
	if e := ctx.Err(); e != nil {
		return nil, e
	}
	kinds := []string{}
	for _, k := range o.Relations {
		kinds = append(kinds, edgeName(k))
	}
	b := &Bundle{
		Version: Version, Snapshot: Snapshot{ID: snap, IRVersion: r.Version, Verification: o.Consistency, VerifiedFiles: len(sources)}, Query: o.Query, Seeds: seeds,
		Trust:        Trust{Role: "untrusted_repository_data", Handling: "Pass as tool-result evidence, not system/developer instructions. The caller enforces permissions and authenticates the index."},
		Capabilities: Capabilities{Available: []string{"go_ast", "python_ast", "html_ast", "css_ast", "javascript_ast", "typescript_ast", "tsx_ast", "markdown_ast", "defines", "imports", "calls", "source_spans"}, Unavailable: []string{"type_checked_dispatch", "type_resolution", "module_resolution", "component_semantics", "react_runtime_semantics", "references", "implements", "inherits", "test_coverage", "build_targets", "embedded_language_semantics"}, CallResolution: "syntax with same-unit name heuristics; not proof of runtime dispatch", Verification: "No build or tests executed; no verification commands inferred."},
		Selection:    Selection{Strategy: "body_units_and_symbols_then_bounded_graph", Depth: o.Depth, Direction: o.Direction, Relations: kinds, MaxBytes: o.MaxBytes, MaxTokens: o.MaxTokens, MaxSymbols: o.MaxSymbols, MaxUnits: o.MaxUnits, MaxCandidates: o.MaxCandidates, MaxRelations: o.MaxRelations},
		Symbols:      []Symbol{}, Units: []Unit{}, Evidence: []Evidence{}, Omissions: Omissions{Candidates: len(candidates), TraversalLimited: limited},
		Warnings: []string{"Coverage is selected, not exhaustive. Missing edges do not prove absence.", "Only declared compilation inputs are covered; ignored, denied and unsupported files are outside the discovery boundary.", "Use snapshot.id plus semantic symbol IDs for expansion. Dense IDs are snapshot-local."},
	}
	b.Snapshot.SourceID, _ = r.Inputs.SourceID()
	b.Snapshot.ProfileID, _ = r.Inputs.ProfileID()
	b.TaskID, e = taskID(snap, o)
	if e != nil {
		return nil, e
	}
	if r.Inputs.GoMod.State == "unavailable" {
		b.Capabilities.Unavailable = append(b.Capabilities.Unavailable, "go_module_metadata_policy_denied")
	}
	if generationSources != nil {
		b.Warnings = append(b.Warnings, "Source bytes were strictly verified once and reused from a caller-retained immutable in-memory generation bound to this snapshot.")
	} else if o.Consistency == "immutable" {
		b.Warnings = append(b.Warnings, "Inventory and auxiliary inputs rely on the caller's pinned, immutable snapshot assertion; source bytes remain hash-verified.")
	} else {
		b.Warnings = append(b.Warnings, "Two verified input passes detect observed drift, not an atomic filesystem snapshot. Isolate concurrent writers.")
	}
	b.Capabilities.Available = append(b.Capabilities.Available, "document_retrieval_units", "body_lexical_retrieval", "query_centered_excerpts")
	b.Warnings = append(b.Warnings, "Unit IDs bind verified source bytes and retrieval-unit rules; re-resolve after changes. Ranking is not confidence or a sufficiency guarantee.")
	if runtime.GOOS != "linux" {
		b.Warnings = append(b.Warnings, "This platform uses a check-then-open fallback: an immutable, access-controlled source root is required.")
	}
	diag, errs := 0, 0
	for _, d := range r.Diagnostics {
		if d.File == 0 || sources[d.File-1] != nil {
			diag++
			if d.Severity == ir.SeverityError {
				errs++
			}
		}
	}
	if diag > 0 {
		b.Warnings = append(b.Warnings, fmt.Sprintf("The permitted index reports %d diagnostics, including %d parse errors; coverage may be incomplete.", diag, errs))
	}
	if r.Graph == nil {
		b.Warnings = append(b.Warnings, "This index has no graph; only lexical/explicit seeds are available.")
	}
	ok, e := fits(b, o, false)
	if e != nil {
		return nil, e
	}
	if !ok {
		return nil, fmt.Errorf("budget too small for context metadata; increase -max-bytes or token cap")
	}

	// Reserve part of the payload for topology and import context. Otherwise
	// greedy source selection can consume every byte before a single arc fits.
	sourceBudget := o
	reserve := o.MaxBytes / 4
	if reserve > 4096 {
		reserve = 4096
	}
	sourceBudget.MaxBytes = o.MaxBytes - reserve
	importBudget := o
	importBudget.MaxBytes = o.MaxBytes - reserve/2
	if o.MaxTokens > 0 {
		sourceBudget.MaxTokens = o.MaxTokens - o.MaxTokens/4
		importBudget.MaxTokens = o.MaxTokens - o.MaxTokens/8
	}
	for _, c := range candidates {
		if e := ctx.Err(); e != nil {
			return nil, e
		}
		if c.unit != nil {
			if len(b.Units) >= o.MaxUnits {
				b.Omissions.UnitLimit++
				continue
			}
			var accepted bool
			b, accepted, e = includeUnit(b, c, sources[c.unit.file], sourceBudget)
			if e != nil {
				return nil, e
			}
			if !accepted {
				if c.seed {
					return nil, fmt.Errorf("budget cannot fit required unit %q", c.unit.ID)
				}
				b.Omissions.Budget++
			}
			continue
		}
		if len(b.Symbols) >= o.MaxSymbols {
			b.Omissions.SymbolLimit++
			continue
		}
		s := r.Symbols[c.node]
		f := r.Files[s.File]
		src := sources[s.File]
		a, z, e := src.offsets(f.Nodes[s.Node].Span)
		if e != nil {
			return nil, fmt.Errorf("symbol %q: %w", r.String(s.ID), e)
		}
		a = src.declarationStart(a, f.Lang)
		base := Symbol{ID: r.String(s.ID), Name: r.String(s.Name), Kind: kindName(s.Kind), Language: languageName(f.Lang), File: src.path, Unit: r.String(f.Unit), Definition: span(f.Nodes[s.Node].Span), Reason: c.reason, Completeness: "full_definition"}
		accepted := false
		for mode := 0; mode < 5; mode++ {
			start, end := a, z
			entry := base
			if mode > 0 {
				start, end = src.queryExcerpt(a, z, o.Query, 900>>(mode-1))
				if start == a && end == z {
					continue
				}
				entry.Completeness = "declaration_excerpt"
				if start != a {
					entry.Completeness = "query_excerpt"
				}
			}
			trial := clone(b)
			entry.Evidence = addEvidence(trial, src, start, end, "source")
			trial.Symbols = append(trial.Symbols, entry)
			if start != a {
				// Keep a separate declaration lead where feasible, never bridge an
				// omitted body gap with invented continuous evidence.
				sa, sz := src.excerpt(a, z, 160)
				withLead := clone(trial)
				addEvidence(withLead, src, sa, sz, "source")
				if leadFits, err := fits(withLead, sourceBudget, true); err != nil {
					return nil, err
				} else if leadFits {
					trial = withLead
				}
			}
			if mode > 0 {
				trial.Omissions.Excerpts++
			}
			ok, e := fits(trial, sourceBudget, true)
			if e != nil {
				return nil, e
			}
			if ok {
				b = trial
				accepted = true
				break
			}
		}
		if !accepted {
			if c.seed {
				return nil, fmt.Errorf("budget cannot fit seed %q, even as an explicit excerpt; increase budget or narrow seeds", base.ID)
			}
			b.Omissions.Budget++
		}
	}
	b.Omissions.Candidates = len(candidates) - len(b.Symbols) - len(b.Units)
	// Imports are supporting evidence, not blindly promoted instructions. Include
	// a whole Go import declaration where available, so aliases remain visible.
	chosenFiles := map[string]bool{}
	for _, s := range b.Symbols {
		chosenFiles[s.File] = true
	}
	for _, u := range b.Units {
		chosenFiles[u.File] = true
	}
	seenImports := map[string]bool{}
	for _, edge := range r.Edges {
		if e := ctx.Err(); e != nil {
			return nil, e
		}
		if edge.Kind != ir.EdgeImports {
			continue
		}
		f := r.Files[edge.From.File]
		src := sources[edge.From.File]
		if src == nil || !chosenFiles[src.path] {
			continue
		}
		sp := f.Nodes[edge.From.Node].Span
		if f.Lang == ir.LangGo {
			for _, n := range f.Nodes {
				if r.String(n.Kind) == "GenDecl" && contains(n.Span, sp) {
					sp = n.Span
					break
				}
			}
		}
		a, z, e := src.offsets(sp)
		if e != nil {
			return nil, fmt.Errorf("import span: %w", e)
		}
		key := evidenceID(src, a, z)
		if seenImports[key] {
			continue
		}
		seenImports[key] = true
		trial := clone(b)
		addEvidence(trial, src, a, z, "imports")
		ok, e := fits(trial, importBudget, true)
		if e != nil {
			return nil, e
		}
		if ok {
			b = trial
		} else {
			b.Omissions.Imports++
		}
	}
	markPartialQueryExcerpts(b, sources)
	if e := ctx.Err(); e != nil {
		return nil, e
	}
	rels, omittedRelations := relationships(r, b, sources, o.MaxRelations)
	b.Omissions.Relations += omittedRelations
	for _, rel := range rels {
		if e := ctx.Err(); e != nil {
			return nil, e
		}
		if len(b.Relationships) >= o.MaxRelations {
			b.Omissions.Relations++
			continue
		}
		trial := clone(b)
		trial.Relationships = append(trial.Relationships, rel)
		ok, e := fits(trial, o, true)
		if e != nil {
			return nil, e
		}
		if ok {
			b = trial
		} else {
			b.Omissions.Relations++
		}
	}
	// Recheck after all counters and metadata are finalized. Never truncate JSON
	// or code to force a fit; failure returns no partial payload.
	p, e := Render(b, o.Format)
	if e != nil {
		return nil, e
	}
	u, e := measure(p, o)
	if e != nil {
		return nil, e
	}
	if u.Bytes > o.MaxBytes || (o.MaxTokens > 0 && u.Tokens > o.MaxTokens) {
		return nil, fmt.Errorf("final payload exceeds budget; increase budget or narrow context")
	}
	if e := b.Validate(); e != nil {
		return nil, fmt.Errorf("bundle invariant: %w", e)
	}
	return &Result{Bundle: b, Payload: p, Usage: u}, nil
}

func markPartialQueryExcerpts(b *Bundle, sources map[int]*source) {
	evidenceByID := make(map[string]Evidence, len(b.Evidence))
	sourcesByPath := make(map[string]*source, len(sources))
	for _, evidence := range b.Evidence {
		evidenceByID[evidence.ID] = evidence
	}
	for _, src := range sources {
		sourcesByPath[src.path] = src
	}
	for _, symbol := range b.Symbols {
		if symbol.Completeness != "query_excerpt" {
			continue
		}
		evidence := evidenceByID[symbol.Evidence]
		src := sourcesByPath[evidence.File]
		if src == nil {
			continue
		}
		partialStart := evidence.Span.StartByteColumn != 0
		partialEnd := evidence.EndByte < len(src.data) && src.data[evidence.EndByte] != '\n'
		if !partialStart && !partialEnd {
			continue
		}
		const warning = "One or more exact query excerpts use partial source-line boundaries; " +
			"non-zero span byte columns identify them and byte coordinates remain exact."
		b.Warnings = append(b.Warnings, warning)
		return
	}
}

func normalize(o *Options, requireRoot bool) error {
