	permitted := func(n int) bool { return n >= len(r.Symbols) || sources[r.Symbols[n].File] != nil }
	add := func(from, to int, k ir.EdgeKind, w uint32) {
		a := key{from, to, k}
		if seen[a] || !permitted(from) || !permitted(to) {
