465			if sym.Kind != ir.SymFunction && sym.Kind != ir.SymMethod && sym.Kind != ir.SymType {
466				continue
467			}
468			f := repo.Files[sym.File]
469			key := fmt.Sprintf("%d:%s:%s:%s", f.Lang, filepath.Dir(stringAt(values, f.Path)), stringAt(values, f.Unit), stringAt(values, sym.Name))
470			byName[key] = append(byName[key], i)
471		}
472		for i := range repo.Edges {
473			e := &repo.Edges[i]
474			if e.Kind != ir.EdgeCalls || e.Text == 0 {
475				continue
476			}
477			f := repo.Files[e.From.File]
478			raw := stringAt(values, e.Text)
479			name := raw
480			if p := strings.LastIndex(raw, "."); p >= 0 {
481				name = raw[p+1:]
482			}
483			key := fmt.Sprintf("%d:%s:%s:%s", f.Lang, filepath.Dir(stringAt(values, f.Path)), stringAt(values, f.Unit), name)
484			if matches := byName[key]; len(matches) == 1 {
485				e.ToSymbol = matches[0] + 1
